import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword for a newcomer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet for a newcomer → 60 + 6 + 5 = 71 G");
    it.todo("plain staff for a newcomer → 80 + 8 + 5 = 93 G");
    it.todo("plain potion for a newcomer → 40 + 4 + 5 = 49 G");
    it.todo("single rune → 25 G base premium (25 + 2.5 + 5 = 32.5 → 33 G)");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium (premium 60 G)");
    it.todo("3 runes → 60 G base premium, block applies (premium 71 G)");
    it.todo("4 runes → 100 G base premium, no block (premium 115 G)");
    it.todo("7 runes → 175 G base premium (premium 197.5 → 198 G)");
    it.todo("2 runes + 1 moonstone → 75 G base premium, different types (premium 87.5 → 88 G)");
    it.todo("3 runes + 3 moonstones → 120 G base premium, two separate blocks (premium 137 G)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword for a newcomer → 100 + 50 curse + 10 first + 5 fee = 165 G");
    it.todo("sword with enchantment exactly 5 → high-enchantment surcharge applies (100 + 30 + 10 + 5 = 145 G)");
    it.todo("cursed sword with enchantment 5 → both surcharges apply (100 + 50 + 30 + 10 + 5 = 195 G)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge (115 G)");
    it.todo("cursed sword with enchantment 4 → only curse surcharge (165 G)");
    it.todo("cursed sword + plain amulet → surcharge only on the sword: 160 base + 50 curse + 16 first + 5 fee = 231 G");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years → loyalty discount applies (100 − 20 + 10 + 5 = 95 G)");
    it.todo("customer with 1 year → no loyalty discount (115 G)");
    it.todo("second quote in a scenario gets 15 % follow-up discount (100 + 10 − 15 + 5 = 100 G)");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → 160 G");
    it.todo("premium fractions are rounded up in the MHPCO's favor (7 runes → 198 G)");
  });

  describe("claim — reimbursement", () => {
    it.todo("regular steel sword enchantment 3, damage 500 G → payout 400 G, remainingCap 1600 G");
    it.todo("rune damaged by 200 G → payout 100 G");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword enchantment 8, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G");
    it.todo("damage smaller than the deductible → payout 0 G");
    it.todo("payout fractions are rounded down in the MHPCO's favor (enchantment 9, damage 901 → 350.5 → 350 G)");
  });

  describe("claim — deductible per damaged item", () => {
    it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 G");
    it.todo("two swords insured, both damaged → each entry has its own deductible");
  });

  describe("claim — cap", () => {
    it.todo("sword + amulet policy → cap 3200 G (remainingCap after small claim reflects it)");
    it.todo("cursed sword → cap 2000 G based on unmodified insurance value");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G");
    it.todo("two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two successive claims of 1500 G on a sword → payouts 1400 then 600, remainingCap 600 then 0");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type (broomstick) → throws");
    it.todo("claim for an item not in the policy (amulet when only a sword is insured) → throws");
    it.todo("claim for an unknown item type → throws");
    it.todo("claim with more damages of a type than insured (two swords, one insured) → throws");
    it.todo("claim with negative amount (-200) → throws");
  });

  describe("scenario", () => {
    it.todo("schema example: returns results for quote and claim steps in order");
  });
});

