export interface ScenarioOutcome {
  results: any[];
}

const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };

const RUNES_PER_BLOCK = 3;
const RUNE_BLOCK_PREMIUM = 60; // building block of 3 alike runes

const roundInMHPCOsFavor = (gold: number): number => Math.ceil(gold);

const sumOfItemPremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const basePremiumOf = (items: Item[]): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  return runeCount === RUNES_PER_BLOCK ? RUNE_BLOCK_PREMIUM : sumOfItemPremiums(items);
};

const quotePremium = (items: Item[]): number => {
  const basePremium = basePremiumOf(items);
  const firstInsuranceSurcharge = basePremium / 10; // 10%, divided to stay float-safe
  return roundInMHPCOsFavor(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const processScenario = (scenario: Scenario): ScenarioOutcome => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(quoteStep.items) }] };
};

