content.content:
const settleClaim = (insuredItems: Item[], incident: Incident): { payout: number; remainingCap: number } => {
  const claimCap = CLAIM_CAP_MULTIPLIER * insuranceSumOf(insuredItems);
  const payout = roundPayoutInMHPCOsFavor(sumOf(incident.damages, (damage) => payoutForDamage(insuredItems, damage)));
  return { payout, remainingCap: claimCap - payout };
};

type QuoteStep = Extract<Step, { op: "quote" }>;

export const processScenario = (scenario: Scenario): ScenarioOutcome => {
  const results = scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      const policy = scenario.steps[step.policy] as QuoteStep;
      return settleClaim(policy.items, step.incident);
    }
    return { premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO, index > 0) };
  });
  return { results };
};

